INSERT INTO `missingpersons` VALUES (9,6,'Nguyễn Văn Thành','Cụ ông 75 tuổi, tóc bạc, đi cà thọt, mặc áo sơ mi kẻ xanh trắng và quần tây đen. Cụ bị lẫn, có thể không nhớ đường về. Rất mong ai biết thông tin hãy liên hệ gấp.','Khu vực cầu Sông Hàn, đường Trần Phú, Đà Nẵng',16.06780000,108.22350000,'https://randomuser.me/api/portraits/men/75.jpg',1,'2025-04-20 07:30:00',NULL);
INSERT INTO `missingpersons` VALUES (10,7,'Trần Bảo Nhi','Bé gái 6 tuổi, cao khoảng 1.1m, tóc đen ngắn, mặc váy hoa hồng. Bé bị lạc khi đi chợ cùng mẹ vào buổi sáng. Bé tên Nhi, hay khóc khi gặp người lạ.','Chợ Hàn, đường Trần Phú, Hải Châu, Đà Nẵng',16.06520000,108.22310000,'https://randomuser.me/api/portraits/women/12.jpg',2,'2025-04-18 09:15:00',NULL);
INSERT INTO `missingpersons` VALUES (11,8,'Lê Hoàng Nam','Nam thanh niên 22 tuổi, cao 1.72m, gầy, tóc cắt ngắn. Mặc áo phông màu trắng có in logo, quần short đen, đeo balo màu xám. Lần cuối được nhìn thấy tại khu vực bãi biển Mỹ Khê vào tối ngày 19/4.','Bãi biển Mỹ Khê, Đà Nẵng',16.03950000,108.24570000,'https://randomuser.me/api/portraits/men/22.jpg',1,'2025-04-19 22:00:00',NULL);
INSERT INTO `missingpersons` VALUES (12,6,'Phạm Thị Hoa','Phụ nữ 55 tuổi, dáng người đậm, tóc ngắn ngang vai, hay mặc áo bà ba. Bà bị bệnh tâm thần nhẹ và thường đi lang thang. Gia đình rất lo lắng.','Khu phố Đa Phước, Hải Châu, Đà Nẵng',16.04230000,108.21860000,NULL,1,'2025-04-22 14:00:00',NULL);
INSERT INTO `missingpersons` VALUES (13,9,'Võ Thanh Tùng','Nam sinh 16 tuổi, học THPT Phan Châu Trinh. Cao khoảng 1.65m, mặc đồng phục trắng xanh. Đi học buổi sáng nhưng tới trưa không về. Điện thoại không liên lạc được.','Trường THPT Phan Châu Trinh, Đà Nẵng',16.06130000,108.21970000,'https://randomuser.me/api/portraits/men/16.jpg',2,'2025-04-15 12:00:00',NULL);
INSERT INTO `missingpersons` VALUES (14,7,'Đỗ Văn Bình','Cụ ông 80 tuổi, đi xe lăn, thường mặc quần áo màu tối. Cụ bị mất tích trong khu vực bệnh viện. Đã được tìm thấy và đưa về gia đình an toàn.','Bệnh viện Đà Nẵng, đường Hải Phòng',16.06490000,108.21550000,NULL,3,'2025-04-10 10:00:00',NULL);
INSERT INTO `missingpersons` VALUES (15,8,'Nguyễn Minh Khoa','Bé trai 4 tuổi, mặc áo thun xanh dương có in xe ô tô, quần short kaki. Bé bị lạc tại công viên 29/3 vào chiều tối. Bé hay gọi \"ba ơi, mẹ ơi\" khi khóc.','Công viên 29/3, Đà Nẵng',16.05820000,108.21420000,'https://randomuser.me/api/portraits/men/4.jpg',1,'2025-04-24 17:30:00',NULL);
